static std::wstring SettingsIniPath() {
    wchar_t path[MAX_PATH]{};
    const DWORD n = GetModuleFileNameW(nullptr, path, MAX_PATH);
    std::wstring out = (n > 0 && n < MAX_PATH) ? std::wstring(path, n) : L"";
    const size_t slash = out.find_last_of(L"\\/");
    if (slash != std::wstring::npos)
        out.resize(slash + 1);
    else
        out.clear();
    out += L"BaccaratCounter.ini";
    return out;
}

static double NormalizeEdgePercent(double pct) {
    if (!std::isfinite(pct)) return 2.0;
    return std::clamp(pct, -20.0, 100.0);
}

static std::optional<double> ParseMinEdgePercentText(std::wstring value) {
    std::replace(value.begin(), value.end(), L',', L'.');
    try {
        size_t used = 0;
        const double pct = std::stod(value, &used);
        while (used < value.size() && std::iswspace(value[used])) ++used;
        if (used == 0 || used != value.size() || !std::isfinite(pct))
            return std::nullopt;
        return NormalizeEdgePercent(pct);
    } catch (...) {
        return std::nullopt;
    }
}

static double LoadMinEdgePercent() {
    wchar_t buf[64]{};
    const auto ini = SettingsIniPath();
    GetPrivateProfileStringW(L"Strategy", L"MinEdgePercent", L"2.00",
                             buf, 64, ini.c_str());
    return ParseMinEdgePercentText(buf).value_or(2.0);
}

static void SaveMinEdgePercent(double pct) {
    pct = NormalizeEdgePercent(pct);
    std::wostringstream os;
    os << std::fixed << std::setprecision(2) << pct;
    const auto ini = SettingsIniPath();
    WritePrivateProfileStringW(L"Strategy", L"MinEdgePercent", os.str().c_str(), ini.c_str());
}

static std::optional<double> ReadMinEdgePercentFromEdit(HWND edit) {
    if (!edit) return std::nullopt;
    wchar_t buf[64]{};
    GetWindowTextW(edit, buf, 64);
    return ParseMinEdgePercentText(buf);
}

// v21.2.106: independent threshold. Stored/displayed in percent, evaluated
