static int NormalizePairChipCents(int cents) {
    return std::clamp(cents, 20, 50000);
}

static std::optional<int> ParsePairChipCentsText(std::wstring value) {
    std::replace(value.begin(), value.end(), L',', L'.');
    try {
        size_t used = 0;
        const double euros = std::stod(value, &used);
        while (used < value.size() && std::iswspace(value[used])) ++used;
        if (used == 0 || used != value.size() || !std::isfinite(euros) || euros <= 0.0)
            return std::nullopt;
        const int cents = static_cast<int>(std::llround(euros * 100.0));
        return NormalizePairChipCents(cents);
    } catch (...) {
        return std::nullopt;
    }
}

static int LoadPairChipCents() {
    wchar_t buf[64]{};
    const auto ini = SettingsIniPath();
    GetPrivateProfileStringW(L"Strategy", L"PairChipEUR", L"2.00", buf, 64, ini.c_str());
    return ParsePairChipCentsText(buf).value_or(200);
}

static void SavePairChipCents(int cents) {
    cents = NormalizePairChipCents(cents);
    std::wostringstream os;
    os << std::fixed << std::setprecision(2) << (static_cast<double>(cents) / 100.0);
    const auto ini = SettingsIniPath();
    WritePrivateProfileStringW(L"Strategy", L"PairChipEUR", os.str().c_str(), ini.c_str());
}

static std::optional<int> ReadPairChipCentsFromEdit(HWND edit) {
    if (!edit) return std::nullopt;
    wchar_t buf[64]{};
    GetWindowTextW(edit, buf, 64);
    return ParsePairChipCentsText(buf);
}

static bool LoadCombinedEvFilterEnabled() {
    wchar_t buf[16]{};
    const auto ini = SettingsIniPath();
    GetPrivateProfileStringW(L"Strategy", L"CombinedEvFilter", L"0",
                             buf, 16, ini.c_str());
    std::wstring value(buf);
    value.erase(std::remove_if(value.begin(), value.end(), [](wchar_t ch) {
        return std::iswspace(ch) != 0;
    }), value.end());
    std::transform(value.begin(), value.end(), value.begin(), [](wchar_t ch) {
        return static_cast<wchar_t>(std::towlower(ch));
    });
    return value == L"1" || value == L"true" || value == L"ein" || value == L"on";
}

static void SaveCombinedEvFilterEnabled(bool enabled) {
    const auto ini = SettingsIniPath();
    WritePrivateProfileStringW(L"Strategy", L"CombinedEvFilter",
                               enabled ? L"1" : L"0", ini.c_str());
}

static std::wstring FormatUnitHundredths(int value) {
    std::wostringstream os;
    if (value > 0) os << L"+";
    const int absolute = std::abs(value);
    os << (value < 0 ? L"-" : L"") << (absolute / 100);
    if (absolute % 100)
        os << L"," << std::setw(2) << std::setfill(L'0') << (absolute % 100);
    return os.str();
}

static int SessionPnlHundredths() {
    return gSessionPnlUnits.load(std::memory_order_acquire) * 100 +
           gSessionMainBetPnlHundredths.load(std::memory_order_acquire);
}

