// v21.2.61: Build the alarm once as a short PCM wave and let winmm play it
// asynchronously. Six blocking Beep calls could start late and break up when
// Chrome, capture I/O and the UI were busy at the same time.
static const std::vector<unsigned char>& SetzenAlarmWave() {
    static const std::vector<unsigned char> wave = [] {
        constexpr int sampleRate = 44100;
        constexpr double pi = 3.14159265358979323846;
        struct Tone { double hz; int ms; int gapMs; };
        constexpr Tone tones[] = {
            { 880.0, 130, 30 },
            { 1175.0, 130, 30 },
            { 1568.0, 230, 70 },
            { 1175.0, 130, 30 },
            { 1760.0, 260, 0 },
        };

        std::vector<std::int16_t> samples;
        for (const auto& tone : tones) {
            const int toneSamples = sampleRate * tone.ms / 1000;
            const int edgeSamples = std::min(toneSamples / 2, sampleRate * 8 / 1000);
            for (int i = 0; i < toneSamples; ++i) {
                double envelope = 1.0;
                if (edgeSamples > 0 && i < edgeSamples)
                    envelope = static_cast<double>(i) / edgeSamples;
                else if (edgeSamples > 0 && i >= toneSamples - edgeSamples)
                    envelope = static_cast<double>(toneSamples - 1 - i) / edgeSamples;
                const double sample = std::sin(2.0 * pi * tone.hz * i / sampleRate);
                samples.push_back(static_cast<std::int16_t>(
                    std::clamp(sample * envelope * 10500.0, -32767.0, 32767.0)));
            }
            samples.insert(samples.end(), sampleRate * tone.gapMs / 1000, 0);
        }

        std::vector<unsigned char> bytes;
        bytes.reserve(44 + samples.size() * sizeof(std::int16_t));
        const auto putText = [&](const char* text, int count) {
            for (int i = 0; i < count; ++i)
                bytes.push_back(static_cast<unsigned char>(text[i]));
        };
        const auto put16 = [&](std::uint16_t value) {
            bytes.push_back(static_cast<unsigned char>(value & 0xff));
            bytes.push_back(static_cast<unsigned char>((value >> 8) & 0xff));
        };
        const auto put32 = [&](std::uint32_t value) {
            for (int shift = 0; shift < 32; shift += 8)
                bytes.push_back(static_cast<unsigned char>((value >> shift) & 0xff));
        };
        const std::uint32_t dataBytes =
            static_cast<std::uint32_t>(samples.size() * sizeof(std::int16_t));
        putText("RIFF", 4); put32(36U + dataBytes); putText("WAVE", 4);
        putText("fmt ", 4); put32(16); put16(1); put16(1);
        put32(sampleRate); put32(sampleRate * 2); put16(2); put16(16);
        putText("data", 4); put32(dataBytes);
        for (const std::int16_t value : samples)
            put16(static_cast<std::uint16_t>(value));
        return bytes;
    }();
    return wave;
}

static void PlaySetzenAlarm() {
    const ULONGLONG now = GetTickCount64();
    ULONGLONG previous = gLastSetzenAlarmTick.load(std::memory_order_acquire);
    for (;;) {
        if (previous != 0 && now >= previous && now - previous < 1100ULL)
            return;
        if (gLastSetzenAlarmTick.compare_exchange_weak(
                previous, now, std::memory_order_acq_rel))
            break;
    }
    const auto& wave = SetzenAlarmWave();
    PlaySoundA(reinterpret_cast<LPCSTR>(wave.data()), nullptr,
               SND_MEMORY | SND_ASYNC | SND_NODEFAULT);
}


