static std::wstring Utf8ToWide(const std::string& s) {
    if (s.empty()) return L"";
    int n = MultiByteToWideChar(CP_UTF8, 0, s.data(), static_cast<int>(s.size()), nullptr, 0);
    if (n <= 0) return L"";
    std::wstring out(n, L'\0');
    MultiByteToWideChar(CP_UTF8, 0, s.data(), static_cast<int>(s.size()), out.data(), n);
    return out;
}

static std::string WideToUtf8(const std::wstring& s) {
    if (s.empty()) return {};
    int n = WideCharToMultiByte(CP_UTF8, 0, s.data(), static_cast<int>(s.size()), nullptr, 0, nullptr, nullptr);
    if (n <= 0) return {};
    std::string out(n, '\0');
    WideCharToMultiByte(CP_UTF8, 0, s.data(), static_cast<int>(s.size()), out.data(), n, nullptr, nullptr);
    return out;
}

static std::string JsonEscape(const std::string& s) {
    std::ostringstream o;
    for (unsigned char c : s) {
        switch (c) {
            case '"': o << "\\\""; break;
            case '\\': o << "\\\\"; break;
            case '\b': o << "\\b"; break;
            case '\f': o << "\\f"; break;
            case '\n': o << "\\n"; break;
            case '\r': o << "\\r"; break;
            case '\t': o << "\\t"; break;
            default:
                if (c < 0x20) {
                    o << "\\u" << std::hex << std::setw(4) << std::setfill('0') << static_cast<int>(c) << std::dec;
                } else {
                    o << static_cast<char>(c);
                }
        }
    }
    return o.str();
}


struct TelegramConfig {
    bool enabled{false};
    std::string botToken;
    std::string chatId;
};

static TelegramConfig LoadTelegramConfig() {
    TelegramConfig cfg;
    const auto ini = SettingsIniPath();
    wchar_t enabled[16]{};
    wchar_t token[256]{};
    wchar_t chatId[96]{};
    GetPrivateProfileStringW(L"Telegram", L"Enabled", L"0", enabled, 16, ini.c_str());
    GetPrivateProfileStringW(L"Telegram", L"BotToken", L"", token, 256, ini.c_str());
    GetPrivateProfileStringW(L"Telegram", L"ChatId", L"", chatId, 96, ini.c_str());
    const std::wstring enabledText(enabled);
    cfg.enabled = enabledText == L"1" || enabledText == L"true" || enabledText == L"TRUE";
    cfg.botToken = WideToUtf8(token);
    cfg.chatId = WideToUtf8(chatId);
    return cfg;
}

static void SaveTelegramChatId(const std::string& chatId) {
    if (chatId.empty()) return;
    const auto ini = SettingsIniPath();
    WritePrivateProfileStringW(L"Telegram", L"ChatId",
                               Utf8ToWide(chatId).c_str(), ini.c_str());
}

static std::wstring NormalizeTelegramBotToken(std::wstring token) {
    while (!token.empty() && std::iswspace(token.front())) token.erase(token.begin());
    while (!token.empty() && std::iswspace(token.back())) token.pop_back();
    return token;
}

static void SaveTelegramBotToken(const std::wstring& rawToken) {
    const std::wstring token = NormalizeTelegramBotToken(rawToken);
    const auto ini = SettingsIniPath();
    WritePrivateProfileStringW(L"Telegram", L"BotToken", token.c_str(), ini.c_str());
    // v21.2.97: maintaining the token in the GUI replaces manual INI editing.
    // A non-empty token therefore enables Telegram globally; clearing it disables it.
    WritePrivateProfileStringW(L"Telegram", L"Enabled",
                               token.empty() ? L"0" : L"1", ini.c_str());
}

static bool LoadTelegramSignalEnabled() {
    wchar_t buf[16]{};
    const auto ini = SettingsIniPath();
    GetPrivateProfileStringW(L"Telegram", L"SignalEnabled", L"0", buf, 16, ini.c_str());
    std::wstring value(buf);
    value.erase(std::remove_if(value.begin(), value.end(), [](wchar_t ch) {
        return std::iswspace(ch) != 0;
    }), value.end());
    std::transform(value.begin(), value.end(), value.begin(), [](wchar_t ch) {
        return static_cast<wchar_t>(std::towlower(ch));
    });
    return value == L"1" || value == L"true" || value == L"ein" || value == L"on";
}

static void SaveTelegramSignalEnabled(bool enabled) {
    const auto ini = SettingsIniPath();
    WritePrivateProfileStringW(L"Telegram", L"SignalEnabled",
                               enabled ? L"1" : L"0", ini.c_str());
}

static void EnsureTelegramIniTemplate() {
    const auto ini = SettingsIniPath();
    wchar_t marker[16]{};
    GetPrivateProfileStringW(L"Telegram", L"Enabled", L"", marker, 16, ini.c_str());
    if (marker[0] == L'\0') {
        WritePrivateProfileStringW(L"Telegram", L"Enabled", L"0", ini.c_str());
        WritePrivateProfileStringW(L"Telegram", L"BotToken", L"", ini.c_str());
        WritePrivateProfileStringW(L"Telegram", L"ChatId", L"", ini.c_str());
    }
    wchar_t signalMarker[16]{};
    GetPrivateProfileStringW(L"Telegram", L"SignalEnabled", L"", signalMarker, 16, ini.c_str());
    if (signalMarker[0] == L'\0')
        WritePrivateProfileStringW(L"Telegram", L"SignalEnabled", L"0", ini.c_str());
}

static bool TelegramApiPost(const std::string& botToken,
                            const std::wstring& method,
                            const std::string& body,
                            std::string& response) {
    response.clear();
    if (botToken.empty()) return false;

    HINTERNET session = WinHttpOpen(
        L"BaccaratCounter/21.2.108",
        WINHTTP_ACCESS_TYPE_AUTOMATIC_PROXY,
        WINHTTP_NO_PROXY_NAME, WINHTTP_NO_PROXY_BYPASS, 0);
    if (!session) return false;
    WinHttpSetTimeouts(session, 3500, 3500, 5000, 5000);

    HINTERNET connect = WinHttpConnect(
        session, L"api.telegram.org", INTERNET_DEFAULT_HTTPS_PORT, 0);
    if (!connect) {
        WinHttpCloseHandle(session);
        return false;
    }

    const std::wstring path = L"/bot" + Utf8ToWide(botToken) + L"/" + method;
    HINTERNET request = WinHttpOpenRequest(
        connect, L"POST", path.c_str(), nullptr, WINHTTP_NO_REFERER,
        WINHTTP_DEFAULT_ACCEPT_TYPES, WINHTTP_FLAG_SECURE);
    if (!request) {
        WinHttpCloseHandle(connect);
        WinHttpCloseHandle(session);
        return false;
    }

    const wchar_t* headers = L"Content-Type: application/json; charset=utf-8\r\n";
    const BOOL sent = WinHttpSendRequest(
        request, headers, static_cast<DWORD>(-1L),
        body.empty() ? WINHTTP_NO_REQUEST_DATA :
            reinterpret_cast<LPVOID>(const_cast<char*>(body.data())),
        static_cast<DWORD>(body.size()), static_cast<DWORD>(body.size()), 0);
    bool ok = sent && WinHttpReceiveResponse(request, nullptr);

    DWORD status = 0;
    DWORD statusSize = sizeof(status);
    if (ok) {
        ok = WinHttpQueryHeaders(
            request, WINHTTP_QUERY_STATUS_CODE | WINHTTP_QUERY_FLAG_NUMBER,
            WINHTTP_HEADER_NAME_BY_INDEX, &status, &statusSize,
            WINHTTP_NO_HEADER_INDEX) && status >= 200 && status < 300;
    }

    if (sent) {
        for (;;) {
            DWORD available = 0;
            if (!WinHttpQueryDataAvailable(request, &available) || available == 0)
                break;
            std::string chunk(available, '\0');
            DWORD read = 0;
            if (!WinHttpReadData(request, chunk.data(), available, &read) || read == 0)
                break;
            chunk.resize(read);
            response += chunk;
            if (response.size() > 512 * 1024) break;
        }
    }

    WinHttpCloseHandle(request);
    WinHttpCloseHandle(connect);
    WinHttpCloseHandle(session);
    return ok;
}

static std::string ResolveTelegramChatId(TelegramConfig& cfg) {
    if (!cfg.chatId.empty()) return cfg.chatId;
    std::string response;
    if (!TelegramApiPost(cfg.botToken, L"getUpdates", "{\"limit\":20}", response))
        return {};
    try {
        const std::regex chatPattern(
            R"REGEX("chat"\s*:\s*\{[^\}]*"id"\s*:\s*(-?[0-9]+))REGEX");
        std::sregex_iterator it(response.begin(), response.end(), chatPattern);
        const std::sregex_iterator end;
        std::string latest;
        for (; it != end; ++it) latest = (*it)[1].str();
        if (!latest.empty()) {
            cfg.chatId = latest;
            SaveTelegramChatId(latest);
        }
    } catch (...) {}
    return cfg.chatId;
}

static void PostTelegramLog(HWND hwnd, const std::wstring& text) {
    if (!hwnd) return;
    auto* heap = new std::wstring(text);
    if (!PostMessageW(hwnd, WM_APP_LOG, 0, reinterpret_cast<LPARAM>(heap)))
        delete heap;
}

static void QueueTelegramMessage(HWND hwnd, const std::wstring& message) {
    std::thread([hwnd, message] {
        TelegramConfig cfg = LoadTelegramConfig();
        if (!cfg.enabled || cfg.botToken.empty()) {
            PostTelegramLog(hwnd,
                L"TELEGRAM: Benachrichtigung nicht gesendet – in BaccaratCounter.ini unter [Telegram] Enabled=1 und BotToken eintragen.");
            return;
        }
        const std::string chatId = ResolveTelegramChatId(cfg);
        if (chatId.empty()) {
            PostTelegramLog(hwnd,
                L"TELEGRAM: Chat-ID konnte nicht ermittelt werden. Dem Bot zuerst in Telegram eine Nachricht schicken oder ChatId in BaccaratCounter.ini eintragen.");
            return;
        }
        const std::string body =
            "{\"chat_id\":\"" + JsonEscape(chatId) +
            "\",\"text\":\"" + JsonEscape(WideToUtf8(message)) +
            "\",\"disable_notification\":false}";
        std::string response;
        const bool ok = TelegramApiPost(cfg.botToken, L"sendMessage", body, response);
        PostTelegramLog(hwnd, ok
            ? L"TELEGRAM: Nachricht gesendet."
            : L"TELEGRAM: Nachricht konnte nicht gesendet werden; Scanner/Autobet läuft unabhängig davon weiter.");
    }).detach();
}

static void QueueTelegramSignalResult(HWND hwnd, const std::wstring& message) {
    if (!gTelegramSignalEnabled.load(std::memory_order_acquire)) return;
    QueueTelegramMessage(hwnd, message);
}

static std::wstring TelegramCurrencyLabel(int currencyCode) {
    return currencyCode == 1 ? L"EUR" :
           currencyCode == 2 ? L"USD" :
           currencyCode == 3 ? L"GBP" : L"";
}

static std::wstring FormatTelegramMoneyMinor(std::int64_t minorUnits,
                                             int currencyCode) {
    const bool negative = minorUnits < 0;
    const std::uint64_t absolute = negative
        ? static_cast<std::uint64_t>(-(minorUnits + 1)) + 1ULL
        : static_cast<std::uint64_t>(minorUnits);
    std::wstring whole = std::to_wstring(absolute / 100ULL);
    for (std::ptrdiff_t pos = static_cast<std::ptrdiff_t>(whole.size()) - 3;
         pos > 0; pos -= 3) {
        whole.insert(static_cast<std::size_t>(pos), 1, L'.');
    }
    std::wostringstream out;
    if (negative) out << L'-';
    out << whole << L',' << std::setw(2) << std::setfill(L'0')
        << (absolute % 100ULL);
    const std::wstring currency = TelegramCurrencyLabel(currencyCode);
    if (!currency.empty()) out << L' ' << currency;
    return out.str();
}

static std::wstring FormatTelegramStakeCents(int cents, int currencyCode) {
    if (cents < 0) cents = 0;
    return FormatTelegramMoneyMinor(cents, currencyCode);
}

static void QueueTelegramSignalSettlement(HWND hwnd,
                                          std::wstring message,
                                          std::uint64_t balanceSequenceAtResult) {
    if (!gTelegramSignalEnabled.load(std::memory_order_acquire)) return;
    std::thread([hwnd, message = std::move(message), balanceSequenceAtResult]() mutable {
        // The visible account balance is sampled independently from the game
        // websocket. Give Betify a short post-result window to publish a newer
        // balance so the Telegram summary normally contains the settled value.
        for (int i = 0; i < 40; ++i) {
            if (!gTelegramSignalEnabled.load(std::memory_order_acquire)) return;
            const auto seq = gLatestObservedBalanceSequence.load(std::memory_order_acquire);
            if (seq > balanceSequenceAtResult) break;
            std::this_thread::sleep_for(std::chrono::milliseconds(100));
        }
        if (!gTelegramSignalEnabled.load(std::memory_order_acquire)) return;

        const auto seq = gLatestObservedBalanceSequence.load(std::memory_order_acquire);
        const auto minor = gLatestObservedBalanceMinor.load(std::memory_order_relaxed);
        const int currencyCode =
            gLatestObservedBalanceCurrencyCode.load(std::memory_order_relaxed);
        if (seq != 0 && !TelegramCurrencyLabel(currencyCode).empty()) {
            message += L"\nKontostand: " +
                       FormatTelegramMoneyMinor(minor, currencyCode);
        } else {
            message += L"\nKontostand: nicht verfügbar";
        }
        QueueTelegramSignalResult(hwnd, message);
    }).detach();
}

static std::optional<std::string> ExtractJsonString(const std::string& json, const std::string& key, size_t start = 0) {
    const std::string token = "\"" + key + "\"";
    size_t p = json.find(token, start);
    if (p == std::string::npos) return std::nullopt;
    p = json.find(':', p + token.size());
    if (p == std::string::npos) return std::nullopt;
    ++p;
    while (p < json.size() && isspace(static_cast<unsigned char>(json[p]))) ++p;
    if (p >= json.size() || json[p] != '"') return std::nullopt;
    ++p;

    std::string out;
    while (p < json.size()) {
        char c = json[p++];
        if (c == '"') return out;
        if (c != '\\') { out.push_back(c); continue; }
        if (p >= json.size()) break;
        char e = json[p++];
        switch (e) {
            case '"': out.push_back('"'); break;
            case '\\': out.push_back('\\'); break;
            case '/': out.push_back('/'); break;
            case 'b': out.push_back('\b'); break;
            case 'f': out.push_back('\f'); break;
            case 'n': out.push_back('\n'); break;
            case 'r': out.push_back('\r'); break;
            case 't': out.push_back('\t'); break;
            case 'u': {
                if (p + 4 <= json.size()) {
                    unsigned value = 0;
                    bool ok = true;
                    for (int i = 0; i < 4; ++i) {
                        char h = json[p++];
                        value <<= 4;
                        if (h >= '0' && h <= '9') value |= (h - '0');
                        else if (h >= 'a' && h <= 'f') value |= (h - 'a' + 10);
                        else if (h >= 'A' && h <= 'F') value |= (h - 'A' + 10);
                        else { ok = false; break; }
                    }
                    if (ok) {
                        if (value <= 0x7F) out.push_back(static_cast<char>(value));
                        else if (value <= 0x7FF) {
                            out.push_back(static_cast<char>(0xC0 | (value >> 6)));
                            out.push_back(static_cast<char>(0x80 | (value & 0x3F)));
                        } else {
                            out.push_back(static_cast<char>(0xE0 | (value >> 12)));
                            out.push_back(static_cast<char>(0x80 | ((value >> 6) & 0x3F)));
                            out.push_back(static_cast<char>(0x80 | (value & 0x3F)));
                        }
                    }
                }
                break;
            }
            default: out.push_back(e); break;
        }
    }
    return std::nullopt;
}

static std::vector<std::string> ExtractJsonStringArray(const std::string& json,
                                                       const std::string& key) {
    std::vector<std::string> out;
    const std::string token = "\"" + key + "\"";
    size_t p = json.find(token);
    if (p == std::string::npos) return out;
    p = json.find(':', p + token.size());
    if (p == std::string::npos) return out;
    p = json.find('[', p + 1);
    if (p == std::string::npos) return out;
    ++p;
    while (p < json.size()) {
        while (p < json.size() && isspace(static_cast<unsigned char>(json[p]))) ++p;
        if (p >= json.size() || json[p] == ']') break;
        if (json[p] != '"') { ++p; continue; }
        ++p;
        std::string value;
        while (p < json.size()) {
            char c = json[p++];
            if (c == '"') break;
            if (c == '\\' && p < json.size()) {
                char e = json[p++];
                switch (e) {
                    case '"': value.push_back('"'); break;
                    case '\\': value.push_back('\\'); break;
                    case '/': value.push_back('/'); break;
                    case 'n': value.push_back('\n'); break;
                    case 'r': value.push_back('\r'); break;
                    case 't': value.push_back('\t'); break;
                    default: value.push_back(e); break;
                }
            } else value.push_back(c);
        }
        out.push_back(value);
        while (p < json.size() && json[p] != ',' && json[p] != ']') ++p;
        if (p < json.size() && json[p] == ',') ++p;
    }
    return out;
}

static std::optional<bool> ExtractJsonBool(const std::string& json, const std::string& key, size_t start = 0) {
    const std::string token = "\"" + key + "\"";
    size_t p = json.find(token, start);
    if (p == std::string::npos) return std::nullopt;
    p = json.find(':', p + token.size());
    if (p == std::string::npos) return std::nullopt;
    ++p;
    while (p < json.size() && isspace(static_cast<unsigned char>(json[p]))) ++p;
    if (json.compare(p, 4, "true") == 0) return true;
    if (json.compare(p, 5, "false") == 0) return false;
    return std::nullopt;
}

static std::optional<int> ExtractJsonInt(const std::string& json, const std::string& key, size_t start = 0) {
    const std::string token = "\"" + key + "\"";
    size_t p = json.find(token, start);
    if (p == std::string::npos) return std::nullopt;
    p = json.find(':', p + token.size());
    if (p == std::string::npos) return std::nullopt;
    ++p;
    while (p < json.size() && isspace(static_cast<unsigned char>(json[p]))) ++p;
    bool neg = false;
    if (p < json.size() && json[p] == '-') { neg = true; ++p; }
    if (p >= json.size() || !isdigit(static_cast<unsigned char>(json[p]))) return std::nullopt;
    int v = 0;
    while (p < json.size() && isdigit(static_cast<unsigned char>(json[p]))) {
        v = v * 10 + (json[p++] - '0');
    }
    return neg ? -v : v;
}

static std::optional<double> ExtractJsonDouble(const std::string& json,
                                                   const std::string& key,
                                                   size_t start = 0) {
    const std::string token = "\"" + key + "\"";
    size_t p = json.find(token, start);
    if (p == std::string::npos) return std::nullopt;
    p = json.find(':', p + token.size());
    if (p == std::string::npos) return std::nullopt;
    ++p;
    while (p < json.size() && isspace(static_cast<unsigned char>(json[p]))) ++p;
    if (p >= json.size()) return std::nullopt;

    size_t e = p;
    if (e < json.size() && (json[e] == '-' || json[e] == '+')) ++e;
    bool any = false;
    while (e < json.size() && isdigit(static_cast<unsigned char>(json[e]))) {
        any = true; ++e;
    }
    if (e < json.size() && json[e] == '.') {
        ++e;
        while (e < json.size() && isdigit(static_cast<unsigned char>(json[e]))) {
            any = true; ++e;
        }
    }
    if (e < json.size() && (json[e] == 'e' || json[e] == 'E')) {
        ++e;
        if (e < json.size() && (json[e] == '-' || json[e] == '+')) ++e;
        bool expAny = false;
        while (e < json.size() && isdigit(static_cast<unsigned char>(json[e]))) {
            expAny = true; ++e;
        }
        if (!expAny) return std::nullopt;
    }
    if (!any) return std::nullopt;
    try {
        return std::stod(json.substr(p, e - p));
    } catch (...) {
        return std::nullopt;
    }
}

static std::string IsoNow() {
    SYSTEMTIME st{};
    GetLocalTime(&st);
    char buf[64];
    snprintf(buf, sizeof(buf), "%04u-%02u-%02uT%02u:%02u:%02u.%03u",
             st.wYear, st.wMonth, st.wDay, st.wHour, st.wMinute, st.wSecond, st.wMilliseconds);
    return buf;
}

static std::string SanitizeUrl(std::string url) {
    // Redact known/session-like query parameters without requiring a URL parser.
    // Keep harmless structural flags such as multiTable=true because they are
    // useful for protocol discovery.
    static const std::vector<std::string> keys = {
        "EVOSESSIONID=", "JSESSIONID=", "ssid=", "nonce=", "vvt=",
        "videoSessionId=", "token=", "auth=", "authorization=",
        "jwt=", "session=", "sessionId=", "password=", "cookie=", "secret="
    };
    for (const auto& key : keys) {
        size_t p = 0;
        while ((p = url.find(key, p)) != std::string::npos) {
            size_t valueStart = p + key.size();
            size_t valueEnd = url.find('&', valueStart);
            if (valueEnd == std::string::npos) valueEnd = url.size();
            url.replace(valueStart, valueEnd - valueStart, "<REDACTED>");
            p = valueStart + 10;
        }
    }
    return url;
}

static std::string RedactSensitiveText(std::string s) {
    // Pragmatic discovery captures server -> browser text frames only. Redact
    // common credential/session fields before writing them to JSONL.
    static const std::vector<std::regex> patterns = {
        std::regex(R"REGEX(("(?:token|session|sessionId|JSESSIONID|ssid|auth|authorization|jwt|nonce|password|cookie|secret|credential|userId|screenName|username|displayName|nickname)"\s*:\s*")[^"]*("))REGEX",
                   std::regex_constants::icase),
        std::regex(R"REGEX((JSESSIONID|ssid|token|auth|authorization|jwt|nonce|session|sessionId)=([^&\s]+))REGEX",
                   std::regex_constants::icase)
    };
    try {
        s = std::regex_replace(s, patterns[0], "$1<REDACTED>$2");
        s = std::regex_replace(s, patterns[1], "$1=<REDACTED>");
    } catch (...) {}
    return s;
}

struct WsUrl {
    std::wstring host;
    INTERNET_PORT port{0};
    std::wstring path;
    bool secure{false};
};

static std::optional<WsUrl> ParseWsUrl(const std::string& u8) {
    std::wstring u = Utf8ToWide(u8);
    bool secure = false;
    size_t scheme = 0;
    if (u.rfind(L"ws://", 0) == 0) { secure = false; scheme = 5; }
    else if (u.rfind(L"wss://", 0) == 0) { secure = true; scheme = 6; }
    else return std::nullopt;

    size_t slash = u.find(L'/', scheme);
    std::wstring authority = slash == std::wstring::npos ? u.substr(scheme) : u.substr(scheme, slash - scheme);
    std::wstring path = slash == std::wstring::npos ? L"/" : u.substr(slash);

    std::wstring host = authority;
    INTERNET_PORT port = secure ? INTERNET_DEFAULT_HTTPS_PORT : INTERNET_DEFAULT_HTTP_PORT;
    size_t colon = authority.rfind(L':');
    if (colon != std::wstring::npos && authority.find(L']') == std::wstring::npos) {
        host = authority.substr(0, colon);
        try { port = static_cast<INTERNET_PORT>(std::stoi(authority.substr(colon + 1))); }
        catch (...) { return std::nullopt; }
    }
    return WsUrl{host, port, path, secure};
}

class CaptureWriter {
public:
    CaptureWriter() {
        std::filesystem::create_directories("captures");
        SYSTEMTIME st{}; GetLocalTime(&st);
        wchar_t name[128];
        swprintf_s(name, L"captures\\cpp_capture_%04u%02u%02u_%02u%02u%02u.jsonl",
                   st.wYear, st.wMonth, st.wDay, st.wHour, st.wMinute, st.wSecond);
        path_ = name;
        file_.open(path_, std::ios::out | std::ios::app | std::ios::binary);
        lastFlushTick_ = GetTickCount64();
    }

    ~CaptureWriter() {
        std::lock_guard<std::mutex> g(mu_);
        if (file_) file_.flush();
    }

    void WriteRaw(const std::string& line) {
        std::lock_guard<std::mutex> g(mu_);
        if (!file_) return;
        file_ << line << "\n";
        ++pendingLines_;
        const ULONGLONG now = GetTickCount64();
        // Flushing every JSON line was particularly expensive inside a
        // OneDrive folder. Keep captures crash-resistant without forcing a
        // synchronous disk round trip for every WebSocket frame.
        if (pendingLines_ >= 32 || now < lastFlushTick_ ||
            now - lastFlushTick_ >= 500ULL) {
            file_.flush();
            pendingLines_ = 0;
            lastFlushTick_ = now;
        }
    }

    std::wstring Path() const { return path_.wstring(); }

private:
    std::mutex mu_;
    std::ofstream file_;
    std::filesystem::path path_;
    std::size_t pendingLines_{0};
    ULONGLONG lastFlushTick_{0};
};


