// and are intentionally excluded from strategy, overview statistics and paper P/L.
static bool IsExcludedBaccaratVariantName(const std::string& name) {
    return name == "Big Small Baccarat" ||
           name == "Mega Baccarat" ||
           name == "Amazing Baccarat" ||
           name == "BIG_SMALL_BACCARAT" ||
           name == "MEGA_BACCARAT" ||
           name == "AMAZING_BACCARAT";
}

