                capture_.WriteRaw("{\"kind\":\"HAND_INCOMPLETE\",\"iso\":\"" + IsoNow() +
                                  "\",\"session\":\"" + JsonEscape(sid) + "\",\"payload\":" + payload + "}");

                auto tableid = ExtractJsonString(payload, "tableid");
                auto cardCount = ExtractJsonInt(payload, "cardCount");

                std::wstring msg = L"HAND INCOMPLETE – wird NICHT gezählt";
                if (tableid) msg += L" table=" + Utf8ToWide(*tableid);
