    void MaybeAutoMultiplayHealthWatch() {
        if (provider_ != ProviderMode::PragmaticPlay || startupPrepareOnly_) return;
        const auto now = std::chrono::steady_clock::now();
        if (now - lastMultiplayHealthWatch_ < std::chrono::milliseconds(2000)) return;
        lastMultiplayHealthWatch_ = now;

        const std::vector<std::string> sessions = PragmaticRuntimeSessions();
        if (sessions.empty()) {
            // v21.2.80 self-heal: don't wait for a betting signal to discover
            // that Chrome kept a valid Pragmatic launcher behind a stale blank
            // Target URL. Probe the same safe recovery candidates immediately;
            // HandleConsole promotes the session from docs[0].href.
            const std::vector<std::string> discovery =
                PragmaticRecoveryRuntimeSessions(5);
            const std::string probe = PragmaticProbeScript(0);
            const std::string probeParams =
                "{\"expression\":\"" + JsonEscape(probe) +
                "\",\"awaitPromise\":false,\"returnByValue\":true}";
            for (const auto& sid : discovery)
                SendCommand("Runtime.evaluate", probeParams, sid);
            if (!discovery.empty()) {
                capture_.WriteRaw(
                    "{\"kind\":\"PRAGMATIC_RUNTIME_REDISCOVERY_REQUESTED\",\"iso\":\"" +
                    IsoNow() + "\",\"candidates\":" +
                    std::to_string(discovery.size()) + "}");
            }
            return;
        }

        pragmaticMultiplayLastHealthProbeTick_.store(GetTickCount64(), std::memory_order_relaxed);
        const std::string script = PragmaticMultiplayHealthScript();
        const std::string params =
            "{\"expression\":\"" + JsonEscape(script) +
            "\",\"awaitPromise\":false,\"returnByValue\":true}";
        for (const auto& sid : sessions)
            SendCommand("Runtime.evaluate", params, sid);
    }

    void PragmaticInvalidateForMultiplayFeedStall(const std::string& reason) {
        int trackedInvalidated = 0;
        int pendingEndsInvalidated = 0;
        int sideTables = 0;
        for (auto& kv : pragmaticTables_) {
            if (pragmaticMainTableIds_.find(kv.first) != pragmaticMainTableIds_.end())
                continue;
            ++sideTables;
            auto& st = kv.second;
            bool changed = false;
            if (st.shoeTracked && st.shoeTrusted) {
                st.shoeTrusted = false;
                ++trackedInvalidated;
                changed = true;
            }
            if (st.pendingShoeEnd && st.pendingEndTrusted) {
                st.pendingEndTrusted = false;
                ++pendingEndsInvalidated;
                changed = true;
            }
            if (st.strategyReady || !st.armedSignalGameId.empty()) changed = true;
            st.strategyReady = false;
            st.armedSignalGameId.clear();
            st.armedSignalPairMask = 0;
            PragmaticClearPendingPlacement(st);
            st.lastPostHandAlertSourceGameId.clear();
            st.lastBetsOpenAlertGameId.clear();
            st.lastAutoBetFocusGameId.clear();
            st.pendingSignalForBetsOpen = false;
            st.pendingSignalSourceGameId.clear();
            {
                std::lock_guard<std::mutex> guard(pragmaticBetsOpenMu_);
                pragmaticBetsOpenGameByTable_.erase(kv.first);
            }
            if (changed) {
                st.phase = "MULTIPLAY-Livefeed unterbrochen";
                PostPragmaticStatus(kv.first, st);
            }
        }
        capture_.WriteRaw(
            "{\"kind\":\"PRAGMATIC_MULTIPLAY_FEED_STALL_INVALIDATE\",\"iso\":\"" + IsoNow() +
            "\",\"reason\":\"" + JsonEscape(reason) +
            "\",\"sideTables\":" + std::to_string(sideTables) +
            ",\"trackedShoesInvalidated\":" + std::to_string(trackedInvalidated) +
            ",\"pendingEndsInvalidated\":" + std::to_string(pendingEndsInvalidated) + "}"
        );
        if (trackedInvalidated > 0 || pendingEndsInvalidated > 0)
            Log(L"MULTIPLAY-LIVEFEED – Unterbrechung erkannt; laufende Seitentisch-Schuhe vorsorglich gesperrt.");
    }

    void MaybeRecoverPragmaticMultiplayReadiness() {
        if (provider_ != ProviderMode::PragmaticPlay || startupPrepareOnly_) return;
        if (!pragmaticMultiplayEverReady_.load(std::memory_order_relaxed)) return;

        const ULONGLONG nowTick = GetTickCount64();
        const int recoveryStageNow = pragmaticRecoveryStage_.load(std::memory_order_relaxed);

        // A lightweight Stage-5/6 reopen should finish quickly. If the primary
        // runtime still cannot produce a usable MULTIPLAY view after 15 s,
        // escalate *before* a future signal: reload the Betify page and let the
        // proven login/session recovery validate the real server-side state.
        if (pragmaticReadinessRecoveryActive_.load(std::memory_order_relaxed)) {
            const ULONGLONG started = pragmaticRecoveryStartedTick_.load(std::memory_order_relaxed);
            const ULONGLONG ageMs = started != 0 && nowTick >= started ? nowTick - started : 0ULL;
            if ((recoveryStageNow == 5 || recoveryStageNow == 6) && ageMs >= 15000ULL) {
                const ULONGLONG lastReload = pragmaticConflictLastReloadTick_.load(std::memory_order_relaxed);
                if (lastReload == 0 || (nowTick >= lastReload && nowTick - lastReload >= 120000ULL)) {
                    const std::string owner = PragmaticCurrentBetifyPageSession();
                    if (!owner.empty()) {
                        pragmaticReadinessRecoveryActive_.store(false, std::memory_order_relaxed);
                        pragmaticRecoveryStage_.store(0, std::memory_order_relaxed);
                        counters_.pragmaticRecoveryStage.store(0, std::memory_order_relaxed);
                        PragmaticSetMultiplayConflict("readiness-recovery-timeout");
                        pragmaticConflictLastReloadTick_.store(nowTick, std::memory_order_relaxed);
                        pragmaticConflictReloadPendingTick_.store(nowTick, std::memory_order_relaxed);
                        PragmaticInvalidateForSessionLoss(
                            "MULTIPLAY-Bereitschaft nach 15s nicht wiederhergestellt; Betify-Serverstatus wird neu validiert");
                        capture_.WriteRaw(
                            "{\"kind\":\"PRAGMATIC_MULTIPLAY_READINESS_BETIFY_RELOAD\",\"iso\":\"" +
                            IsoNow() + "\",\"ageMs\":" + std::to_string(ageMs) + "}"
                        );
                        Log(L"MULTIPLAY-BEREITSCHAFT – leichte Wiederherstellung nach 15s erfolglos; Betify wird jetzt kontrolliert neu validiert, bevor ein späteres Signal kommt.");
                        SendCommand("Page.reload", "{\"ignoreCache\":false}", owner);
                    }
                }
                return;
            }
            return;
        }

        if (recoveryStageNow != 0) return;
        if (pragmaticMultiplayConflict_.load(std::memory_order_relaxed)) return;
        const ULONGLONG readyTick = pragmaticMultiplayLastReadyTick_.load(std::memory_order_relaxed);
        const ULONGLONG mainTick = pragmaticMultiplayLastMainReadyTick_.load(std::memory_order_relaxed);
        const ULONGLONG liveTick = pragmaticMultiplayLastLiveFrameTick_.load(std::memory_order_relaxed);
        if (readyTick == 0 || mainTick == 0) return;

        const ULONGLONG readyAge = nowTick >= readyTick ? nowTick - readyTick : 0ULL;
        const ULONGLONG mainAge = nowTick >= mainTick ? nowTick - mainTick : 0ULL;
        const ULONGLONG liveAge = liveTick != 0 && nowTick >= liveTick ? nowTick - liveTick : 0ULL;

        const bool domStale = readyAge >= 8000ULL;
        const bool feedStale = liveTick != 0 && liveAge >= 12000ULL;
        // A stale real game feed is authoritative even if the primary table
        // DOM has also frozen. The previous early return delegated that exact
        // state to a Betify login watcher which could still see the deposit
        // button for hours while Pragmatic itself was disconnected.
        if (mainAge > 7000ULL && !feedStale) return;
        if (!domStale && !feedStale) return;

        const ULONGLONG lastRecovery =
            pragmaticMultiplayLastReadinessRecoveryTick_.load(std::memory_order_relaxed);
        if (lastRecovery != 0 && nowTick >= lastRecovery && nowTick - lastRecovery < 30000ULL)
            return;

        pragmaticMultiplayLastReadinessRecoveryTick_.store(nowTick, std::memory_order_relaxed);
        pragmaticRecoveryStartedTick_.store(nowTick, std::memory_order_relaxed);
        pragmaticRecoveryAutomatic_.store(true, std::memory_order_relaxed);
        counters_.pragmaticRecoveryAutomatic.store(true, std::memory_order_relaxed);
        pragmaticRecoveryStage_.store(5, std::memory_order_relaxed);
        counters_.pragmaticRecoveryStage.store(5, std::memory_order_relaxed);
        pragmaticReadinessRecoveryActive_.store(true, std::memory_order_relaxed);
        lastCardScan_ = std::chrono::steady_clock::time_point{};

        if (feedStale)
            PragmaticInvalidateForMultiplayFeedStall("keine frischen MULTIPLAY-Spieldaten");

        capture_.WriteRaw(
            "{\"kind\":\"PRAGMATIC_MULTIPLAY_READINESS_RECOVERY_ARMED\",\"iso\":\"" + IsoNow() +
            "\",\"reason\":\"" + std::string(feedStale ? "game-data-stale" : "dom-not-ready") +
            "\",\"readyAgeMs\":" + std::to_string(readyAge) +
            ",\"liveAgeMs\":" + std::to_string(liveAge) +
            ",\"mainAgeMs\":" + std::to_string(mainAge) + "}"
        );
        Log(feedStale
            ? L"MULTIPLAY-BEREITSCHAFT – Livefeed ausgefallen; öffne MULTIPLAY sofort neu, bevor ein Signal auftreten kann."
            : L"MULTIPLAY-BEREITSCHAFT – Oberfläche nicht mehr bedienbar; öffne MULTIPLAY sofort neu, ohne Betify neu zu laden.");
    }

