    static std::wstring LowerWindowText(std::wstring s) {
        std::transform(s.begin(), s.end(), s.begin(),
                       [](wchar_t c){ return static_cast<wchar_t>(std::towlower(c)); });
        return s;
    }

    HWND FindBestChromeWindow() const {
        struct SearchState {
            HWND best{};
            int bestScore{-1};
        } state;

        EnumWindows([](HWND w, LPARAM lp) -> BOOL {
            if (!IsWindowVisible(w)) return TRUE;

            wchar_t cls[128]{};
            if (!GetClassNameW(w, cls, static_cast<int>(sizeof(cls)/sizeof(cls[0])))) return TRUE;
            if (std::wstring(cls) != L"Chrome_WidgetWin_1") return TRUE;

            wchar_t title[512]{};
            GetWindowTextW(w, title, static_cast<int>(sizeof(title)/sizeof(title[0])));
            if (!title[0]) return TRUE;

            auto* st = reinterpret_cast<SearchState*>(lp);
            std::wstring t = LowerWindowText(title);
            int score = 10;
            if (GetWindow(w, GW_OWNER) == nullptr) score += 10;
            if (t.find(L"betify") != std::wstring::npos) score += 1000;
            if (t.find(L"baccarat") != std::wstring::npos) score += 250;
            if (t.find(L"pragmatic") != std::wstring::npos) score += 150;
            if (t.find(L"google chrome") != std::wstring::npos) score += 25;

            if (score > st->bestScore) {
                st->bestScore = score;
                st->best = w;
            }
            return TRUE;
        }, reinterpret_cast<LPARAM>(&state));
        return state.best;
    }

    bool ForceForegroundWindow(HWND target) const {
        if (!target || !IsWindow(target)) return false;

        ShowWindowAsync(target, IsIconic(target) ? SW_RESTORE : SW_SHOW);

        HWND foreground = GetForegroundWindow();
        const DWORD thisThread = GetCurrentThreadId();
        const DWORD foregroundThread = foreground
            ? GetWindowThreadProcessId(foreground, nullptr)
            : 0;
        bool attached = false;
        if (foregroundThread && foregroundThread != thisThread) {
            attached = AttachThreadInput(thisThread, foregroundThread, TRUE) != FALSE;
        }

        BringWindowToTop(target);
        SetWindowPos(target, HWND_TOP, 0, 0, 0, 0,
                     SWP_NOMOVE | SWP_NOSIZE | SWP_SHOWWINDOW);
        const bool ok = SetForegroundWindow(target) != FALSE;

        if (attached)
            AttachThreadInput(thisThread, foregroundThread, FALSE);

        if (!ok) {
            FLASHWINFO fi{};
            fi.cbSize = sizeof(fi);
            fi.hwnd = target;
            fi.dwFlags = FLASHW_TRAY | FLASHW_TIMERNOFG;
            fi.uCount = 4;
            fi.dwTimeout = 0;
            FlashWindowEx(&fi);
        }
        return ok || GetForegroundWindow() == target;
    }

    void BringChromeToFrontForRecovery(const std::string& sessionId) {
        // First ask Chrome to select the Betify tab represented by the CDP
        // session. This is navigation/focus only; it does not interact with
        // any betting control.
        if (!sessionId.empty())
            SendCommand("Page.bringToFront", "{}", sessionId);

        HWND chrome = FindBestChromeWindow();
        HWND previous = GetForegroundWindow();
        if (previous && previous != chrome && IsWindow(previous))
            pragmaticRecoveryPreviousForegroundWindow_ = previous;
        else
            pragmaticRecoveryPreviousForegroundWindow_ = nullptr;

        pragmaticRecoveryChromeWindow_ = chrome;
        const bool focused = ForceForegroundWindow(chrome);

        wchar_t title[512]{};
        if (chrome) GetWindowTextW(chrome, title, static_cast<int>(sizeof(title)/sizeof(title[0])));
        capture_.WriteRaw(
            std::string("{\"kind\":\"PRAGMATIC_LOGIN_RECOVERY_CHROME_FOREGROUND\",\"iso\":\"") +
            IsoNow() + "\",\"focused\":" + (focused ? "true" : "false") +
            ",\"windowFound\":" + (chrome ? "true" : "false") +
            ",\"title\":\"" + JsonEscape(WideToUtf8(title)) + "\"}"
        );
        Log(focused
            ? L"AUTO-LOGIN-RECOVERY – Chrome/Betify in den Vordergrund geholt."
            : L"AUTO-LOGIN-RECOVERY – Chrome-Fokus angefordert; Windows hat den Vordergrundwechsel nicht bestätigt.");
    }

    void RestorePreviousForegroundAfterRecovery() {
        HWND previous = pragmaticRecoveryPreviousForegroundWindow_;
        HWND chrome = pragmaticRecoveryChromeWindow_;
        pragmaticRecoveryPreviousForegroundWindow_ = nullptr;
        pragmaticRecoveryChromeWindow_ = nullptr;

        if (!previous || !IsWindow(previous) || previous == chrome) return;

        // Only restore automatically if Chrome is still the foreground window.
        // If the user already switched to another program during recovery,
        // leave that newer choice untouched.
        if (chrome && IsWindow(chrome) && GetForegroundWindow() != chrome) return;

        const bool restored = ForceForegroundWindow(previous);
        capture_.WriteRaw(
            std::string("{\"kind\":\"PRAGMATIC_LOGIN_RECOVERY_FOREGROUND_RESTORED\",\"iso\":\"") +
            IsoNow() + "\",\"restored\":" + (restored ? "true" : "false") + "}"
        );
        if (restored)
            Log(L"AUTO-LOGIN-RECOVERY – vorheriges Arbeitsfenster wieder in den Vordergrund geholt.");
    }

