        case WM_APP_TABLE_STATUS: {
            auto* u = reinterpret_cast<TableStatusUpdate*>(lParam);
            if (a && u && !u->tableId.empty()) {
                auto& row = a->tableOverview[u->tableId];
                row.name = u->name.empty() ? u->tableId : u->name;
                row.status = u->status;
                row.lastSeen = GetTickCount64();
                row.shoeHands = u->shoeHands;
                row.shoeCards = u->shoeCards;
                row.shoeCardsExact = u->shoeCardsExact;
                row.burnCards = u->burnCards;
                row.burnCardsExact = u->burnCardsExact;
                const bool hasDedicatedCards =
                    !u->playerCards.empty() || !u->bankerCards.empty();
                if (hasDedicatedCards) {
                    row.playerCards = PrettyCardList(u->playerCards);
                    row.bankerCards = PrettyCardList(u->bankerCards);
                }
                if (!u->gameId.empty()) row.lastGameId = u->gameId;
                ParseOverviewFields(row, hasDedicatedCards);
                a->overviewDirty = true;
            }
            delete u;
            return 0;
        }
        case WM_APP_TABLE_STRATEGY: {
            auto* u = reinterpret_cast<TableStrategyUpdate*>(lParam);
            if (a && u && !u->tableId.empty()) {
                auto& row = a->tableOverview[u->tableId];
                const int previousSignalRounds = row.signalRounds;
                const int previousWinningRounds = row.winningSignalRounds;
                const int previousSignalHits = row.signalHits;
                const int previousPairBets = row.signalPairBets;
                const bool wasSet = row.signal.rfind(L"SETZEN:",0)==0;
                const std::wstring newSignal=u->signal.empty()?L"–":u->signal;
                const bool nowSet = newSignal.rfind(L"SETZEN:",0)==0;
                row.strategyAvailable=u->available;
                row.pairProbability=u->probability;
                row.edge=u->edge;
                row.signal=newSignal;
                if (u->validSetzenSignals >= 0) {
                    row.validSetzenSignals = u->validSetzenSignals;
                } else if (nowSet && !wasSet) {
                    ++row.validSetzenSignals;
                }
                auto& acc = a->strategyAccumulators[u->tableId];
                const bool hadAccumulator = acc.initialized;
                if(u->signalRounds>=0)
                    row.signalRounds=AccumulateCounter(u->signalRounds, acc.lastRawSignalRounds, acc.totalSignalRounds, hadAccumulator);
                if(u->winningSignalRounds>=0)
                    row.winningSignalRounds=AccumulateCounter(u->winningSignalRounds, acc.lastRawWinningSignalRounds, acc.totalWinningSignalRounds, hadAccumulator);
                if(u->signalHits>=0)
                    row.signalHits=AccumulateCounter(u->signalHits, acc.lastRawSignalHits, acc.totalSignalHits, hadAccumulator);
                if(u->signalPairBets>=0)
                    row.signalPairBets=AccumulateCounter(u->signalPairBets, acc.lastRawSignalPairBets, acc.totalSignalPairBets, hadAccumulator);
                if(u->signalRounds>=0 || u->winningSignalRounds>=0 || u->signalHits>=0 || u->signalPairBets>=0)
                    acc.initialized = true;
                const bool summaryChanged =
                    previousSignalRounds != row.signalRounds ||
                    previousWinningRounds != row.winningSignalRounds ||
                    previousSignalHits != row.signalHits ||
                    previousPairBets != row.signalPairBets;
                if (summaryChanged)
                    RefreshPnlSummary(a, true, u->timestamp);
                a->overviewDirty = true;
                if(nowSet && !wasSet &&
                   !gUnitTargetReached.load(std::memory_order_acquire) &&
                   !gStopLossReached.load(std::memory_order_acquire)) {
                    const std::wstring tableLabel = row.name.empty() ? u->tableId : row.name;
                    if (a->activeProvider == ProviderMode::Evolution &&
                        a->monitor) {
                        a->monitor->PrepareEvolutionActionForSignal(
                            WideToUtf8(u->tableId), WideToUtf8(tableLabel));
                    }
                    AppendLog(a->log,
                        L"SETZEN-HILFE: " + tableLabel +
                        L" – Tisch wird fokussiert; Player Pair + Banker Pair bitte manuell setzen.");
                }
            }
            delete u;
            return 0;
        }
